        "ቃል ሲጨርሱ የተሳሳተ አናባቢ ወይም ተመሳሳይ ድምጽ ፊደል (ሰ ለ ሠ) ያርማል። ሲጠፋ ማስተካከያው አሁንም በጥቆማዎች ውስጥ መጀመሪያ ይቀርባል",
        "ቃል ምስ ኣወዳእካ ጌጋ ደሞ ፊደል ተመሳሳሊ ድምጺ (ሰ ን ሠ) የመሓይሽ። ምስ ዝጠፍእ እቲ ምምሕያሽ ኣብ ጥቆማታት ቀዳማይ ይቐርብ",
        "Yeroo jecha xumurtan qubee sagalee dogoggoraa ykn walfakkaataa (ሰ ykn ሠ) sirreessa. Yoo cufame, sirreeffamni amma iyyuu yaada keessatti durfamee dhiyaata",
        "Wuxuu saxaa shaqal khaldan ama xaraf isku dhawaaq ah (ሰ ama ሠ) marka eray dhammeeyo. Haddii la damiyo, saxitaanka weli waa la soo jeediyaa marka hore",
        "يصحح حرفًا علةً خاطئًا أو حرفًا متشابه النطق (ሰ بدل ሠ) عند إنهاء الكلمة. وإن أُوقف، يظل التصحيح مقترحًا أولًا",
    ),
    "Learn the words I type" to r("የምተይባቸውን ቃላት ተማር", "ዝጽሕፎም ቃላት ተማህር", "Jechoota ani barreessu baradhu", "Baro erayada aan qoro", "تعلّم الكلمات التي أكتبها"),
    "Never in password, email or number fields" to r("በይለፍ ቃል፣ በኢሜይል ወይም በቁጥር መስኮች በፍጹም", "ኣብ ቃል ምስጢር፣ ኢሜይል ወይ ቍጽሪ መዳያ ፈጺሙ", "Gonkumaa dirree jecha darbaa, imeelii ykn lakkoofsaa keessatti", "Marnaba goobaha furaha sirta, email ama lambarka", "أبدًا في حقول كلمة المرور أو البريد أو الأرقام"),
    "Slide across the letters to type a word, in English, phonetic Amharic or on the fidel consonants" to r("ቃል ለመተየብ በፊደላት ላይ ይጎትቱ፣ በእንግሊዝኛ፣ በድምጻዊ አማርኛ ወይም በፊደል ተነባቢዎች", "ቃል ንምጽሓፍ ኣብ ፊደላት ሳሓብ፣ ብእንግሊዝኛ፣ ብድምጻዊ ኣምሓርኛ ወይ ብፊደል ተነባቢታት", "Jecha barreessuuf qubeewwan irra harkisi, Ingliffaa, Amaariffaa sagalee ykn dubbifamoota fidel irratti", "Ku jiid xarfaha si aad eray u qorto, Ingiriisi, Amxaari codka ama shaqalada fidel", "اسحب عبر الحروف لكتابة كلمة بالإنجليزية أو الأمهرية الصوتية أو على صوامت الفيدل"),
    "Long-press popups" to r("ረጅም ጭነት ብቅ-ባዮች", "ናይ ነዊሕ ምጥዋይ ፖፕኣፕ", "Fuula bahu tuqaa dheeraa", "Daaqadaha cadaadis dheer", "نوافذ الضغط المطوّل"),
    "Hold a key for accents and vowel forms" to r("ለአክሰንትና ለአናባቢ ቅርጾች ቁልፍን ይያዙ", "ንኣክሰንትን ንቅርጽታት ድምጺን መፍትሕ ሓዝ", "Mallattoo fi bifa sagalee argachuuf furtuu qabi", "Ku hay furaha si aad u hesho lahjado iyo qaababka shaqalka", "اضغط مطولًا للحصول على اللكنات وأشكال الحروف المتحركة"),
    "Long-press delay" to r("የረጅም ጭነት መዘግየት", "ዝደንጉየሉ ግዜ ነዊሕ ምጥዋይ", "Turtii tuqaa dheeraa", "Daahitaanka cadaadiska dheer", "تأخير الضغط المطوّل"),
    "Hold backspace to delete the sentence" to r("ዓረፍተ ነገሩን ለመሰረዝ ባክስፔስን ይያዙ", "ሓረግ ንምድምሳስ backspace ሓዝ", "Hima haquuf backspace qabi", "Ku hay backspace si aad u tirto jumladda", "اضغط مطولًا على الحذف لمسح الجملة"),
    "Hold time" to r("የመያዣ ጊዜ", "ግዜ ምሓዝ", "Yeroo qabuu", "Waqtiga la hayo", "مدة الضغط"),
    "Capital at the start of a sentence" to r("በዓረፍተ ነገር መጀመሪያ ትልቅ ፊደል", "ኣብ መጀመርታ ሓረግ ዓቢ ፊደል", "Qubee guddaa jalqaba hima", "Xarafka weyn bilowga jumladda", "حرف كبير في بداية الجملة"),
    "Double-space period" to r("ሁለት ክፍት ቦታ = ነጥብ", "ክልተ ስፔስ = ነጥቢ", "Space lama = tuqaa", "Laba space = dhibic", "مسافتان = نقطة"),
    "Two spaces after a word make a full stop" to r("ከቃል በኋላ ሁለት ክፍት ቦታ ነጥብ ይሆናል", "ድሕሪ ቃል ክልተ ስፔስ ነጥቢ ይኸውን", "Space lama jecha booda tuqaa ta'a", "Laba space eray ka dib waxay noqdaan dhibic", "مسافتان بعد الكلمة تصبحان نقطة"),
    "After . ! ? ; : the next letter starts with a space" to r("ከ . ! ? ; : በኋላ ቀጣዩ ፊደል በክፍት ቦታ ይጀምራል", "ድሕሪ . ! ? ; : እቲ ዝቕጽል ፊደል ብስፔስ ይጅምር", "Booda . ! ? ; : qubeen itti aanu space'n jalqaba", "Kadib . ! ? ; : xarafka xiga wuxuu ku bilowdaa space", "بعد . ! ? ; : يبدأ الحرف التالي بمسافة"),

    // Feedback
    "Haptic feedback" to r("የንዝረት ግብረ መልስ", "ናይ ንዘኽታዊ ግብረ መልሲ", "Deebii hollannaa", "Jawaab gariir", "ردود فعل الاهتزاز"),
    "Feel every tap" to r("እያንዳንዱን ንክኪ ይሰማዎታል", "ነፍሲ ወከፍ ንክኪ ትስምዕ", "Tuqaa hunda dhaga'i", "Dareem taabasho kasta", "أحسّ بكل لمسة"),
    "Strength" to r("ጥንካሬ", "ሓይሊ", "Cimina", "Xoog", "القوة"),
    "Subtle click on tap" to r("ሲነኩ ለስላሳ ጠቅታ", "ክትንክፍ ከለኻ ለዝቢ ጠቅታ", "Tuqaa laafaa yeroo tuqamu", "Guji jilicsan marka la taabto", "نقرة خفيفة عند اللمس"),
    "Volume" to r("የድምጽ መጠን", "ዓቐን ድምጺ", "Sagalee", "Mugga codka", "مستوى الصوت"),

    // Toolbar, emoji, stickers
    "Shown left of the suggestions. Settings is always there, and every tool is also inside the emoji panel. With more than three, the toolbar folds behind one button while you type." to r(
        "ከጥቆማዎች በግራ ይታያል። ቅንብሮች ሁልጊዜ አለ፣ እና እያንዳንዱ መሣሪያ በሺሸንፍ ፓነል ውስጥም አለ። ከሦስት በላይ ሲሆኑ ሲተይቡ የመሣሪያ አሞሌው ከአንድ አዝራር ጀርባ ይታጠፋል።",
        "ጸጋም ጥቆማታት ይርአ። ቅጥዕታት ኩሉ ግዜ ኣሎ፣ ኩሉ መሳርሒ ድማ ኣብ ፓነል ኢሞጂ ኣሎ። ልዕሊ ሰለስተ ምስ ዝኾኑ ክትጽሕፍ ከለኻ መሳርሒ ባር ድሕሪ ሓደ ዓቐንቲ ይዕጠፍ።",
        "Bitaa yaadaa agarsiifama. Qindaa'inni yeroo hunda jira, meeshaaleen hundi paanelii emojii keessas jiru. Sadii ol yoo ta'e, gabateen yeroo barreessitan butoonii tokko duubatti marfama.",
        "Waxaa lagu muujiyaa bidixda soo jeedinnada. Dejintu had iyo jeer way joogtaa, qalab kasta waxaa kale oo ku jira guddiga emoji. Haddii ka badan saddex, barka qalabku wuxuu ku laablaa hal badhan marka aad qorto.",
        "يظهر على يسار الاقتراحات. الإعدادات موجودة دائمًا وكل أداة موجودة أيضًا داخل لوحة الرموز. مع أكثر من ثلاثة، ينطوي الشريط خلف زر واحد أثناء الكتابة.",
    ),
    "A row above the toolbar; tap it to type the word" to r("ከመሣሪያ አሞሌ በላይ ያለ ረድፍ፤ ቃሉን ለመተየብ ይንኩት", "ልዕሊ መሳርሒ ባር ዘሎ ረድፊ፤ ቃል ንምጽሓፍ ትንክፎ", "Sarara gabatee meeshaalee gubbaa; jecha barreessuuf tuqi", "Saf ka sarreeya barka qalabka; taabo si aad eraygu u qorto", "صف فوق شريط الأدوات؛ اضغط عليه لكتابة الكلمة"),
    "Default" to r("ነባሪ", "ነባሪ", "Durtii", "Caadi", "الافتراضي"),
    "Paste your key" to r("ቁልፍዎን ይለጥፉ", "መፍትሕኻ ለጥፍ", "Furtuu kee maxxansi", "Ku dheji furahaaga", "الصق مفتاحك"),
    "Optional. GIFs come from Giphy through the Akai server. Paste your own key (free at developers.giphy.com) to ask Giphy directly instead. Kept on this phone only." to r(
        "አማራጭ። GIFዎች ከGiphy በአካይ አገልጋይ በኩል ይመጣሉ። በቀጥታ Giphyን ለመጠየቅ የራስዎን ቁልፍ (በነጻ በdevelopers.giphy.com) ይለጥፉ። በዚህ ስልክ ላይ ብቻ ይቀመጣል።",
        "ኣማራጺ። GIFs ካብ Giphy ብኣገልጋሊ ኣካይ ይመጹ። ብቕጥታ Giphy ንምሕታት ናትካ መፍትሕ (ብነጻ ኣብ developers.giphy.com) ለጥፍ። ኣብዚ ሞባይል ጥራይ ይቕመጥ።",
        "Filannoo. GIF'n Giphy irraa sarvara Akai'tiin dhufa. Giphy kallattiin gaafachuuf furtuu kee mataa kee (bilisaan developers.giphy.com irratti) maxxansi. Bilbila kana irra qofa kuufama.",
        "Ikhtiyaari. GIF-yada waxay ka yimaadaan Giphy iyagoo mara server-ka Akai. Ku dheji furahaaga (bilaash developers.giphy.com) si aad Giphy si toos ah u weydiiso. Waxaa lagu hayaa taleefankan oo keliya.",
        "اختياري. تأتي صور GIF من Giphy عبر خادم Akai. الصق مفتاحك الخاص (مجانًا من developers.giphy.com) للطلب من Giphy مباشرة. يُحفظ على هذا الهاتف فقط.",
    ),
    "Sticker Marketplace" to r("የተለጣፊ ገበያ", "ዕዳጋ ስቲከር", "Gabaa stikeroota", "Suuqa stickers-ka", "سوق الملصقات"),
    "Browse packs and install the ones you like" to r("ጥቅሎችን ያስሱ እና የሚወዷቸውን ይጫኑ", "ጥቕላላት ርአ ዝፈተውካዮም ድማ ጸዓን", "Kuusaawwan ilaali, kan jaallattan fe'i", "Baar xirmooyinka oo rakib kuwa aad jeceshahay", "تصفّح الحزم وثبّت ما يعجبك"),
    "Look at the pack" to r("ጥቅሉን ተመልከት", "ጥቕላል ርአ", "Kuusaa ilaali", "Eeg xirmada", "اعرض الحزمة"),
    "Paste a link like t.me/addstickers/PackName" to r("እንደ t.me/addstickers/PackName ያለ አገናኝ ይለጥፉ", "ከም t.me/addstickers/PackName ዝበለ ሊንክ ለጥፍ", "Linkii akka t.me/addstickers/PackName maxxansi", "Ku dheji xiriir sida t.me/addstickers/PackName", "الصق رابطًا مثل t.me/addstickers/PackName"),
    "Paste a Telegram sticker or emoji pack link (t.me/addstickers/… or t.me/addemoji/…) to see what is in it, then install it. In Telegram, open the pack, tap ⋮ then Copy link. Video stickers move (on Android 9 and newer); vector-animated ones come in as still pictures." to r(
        "በውስጡ ያለውን ለማየት የቴሌግራም ተለጣፊ ወይም ሺሸንፍ ጥቅል አገናኝ (t.me/addstickers/… ወይም t.me/addemoji/…) ይለጥፉ፣ ከዚያ ይጫኑት። በቴሌግራም ጥቅሉን ከፍተው ⋮ ን ነክተው አገናኝ ቅዳ ይምረጡ። የቪዲዮ ተለጣፊዎች ይንቀሳቀሳሉ (አንድሮይድ 9 እና ከዚያ በላይ)፤ በቬክተር የተሠሩ እንደ ቋሚ ምስል ይመጣሉ።",
        "ዘለዎ ንምርአይ ሊንክ ጥቕላል ስቲከር ወይ ኢሞጂ ቴሌግራም (t.me/addstickers/… ወይ t.me/addemoji/…) ለጥፍ፣ ደሓር ጸዓኖ። ኣብ ቴሌግራም ጥቕላል ከፊትካ ⋮ ትንክፍ ድሕሪኡ ሊንክ ቅዳሕ። ቪድዮ ስቲከራት ይንቀሳቐሱ (ኣንድሮይድ 9 ከምኡ ልዕሊኡ)፤ ቬክተር ዝኾኑ ከም ቀይድ ምስሊ ይኣትዉ።",
        "Waan keessa jiru ilaaluuf linkii kuusaa stikeera ykn emojii Teleegraamii (t.me/addstickers/… ykn t.me/addemoji/…) maxxansi, itti aansuun fe'i. Teleegraamii keessatti kuusaa bani, ⋮ tuqi, achiis Copy link filadhu. Stikeroonni viidiyoo ni socho'u (Android 9 fi isa ol); kan vector fakkii dhaabbataa ta'u.",
        "Ku dheji xiriirka xirmada sticker ama emoji ee Telegram (t.me/addstickers/… ama t.me/addemoji/…) si aad u aragto waxa ku jira, kadibna rakib. Telegram, fur xirmada, taabo ⋮ kadibna Copy link. Stickers-ka muuqaalka way dhaqdhaqaaqaan (Android 9 iyo ka sii dambeeya); kuwa vector-ka waxay u yimaadaan sawirro taagan.",
        "الصق رابط حزمة ملصقات أو رموز تيليجرام (t.me/addstickers/… أو t.me/addemoji/…) لرؤية محتواها ثم ثبّتها. في تيليجرام افتح الحزمة واضغط ⋮ ثم نسخ الرابط. ملصقات الفيديو تتحرك (أندرويد 9 فما فوق)؛ أما المتجهية فتأتي كصور ثابتة.",
    ),
    "Packs you add show up here and in the keyboard's sticker tab." to r("የሚጨምሯቸው ጥቅሎች እዚህና በኪቦርዱ ተለጣፊ ትር ውስጥ ይታያሉ።", "ዝወሰኽካዮም ጥቕላላት ኣብዚን ኣብ ታብ ስቲከር ኪቦርድን ይርአዩ።", "Kuusaawwan dabaltan as fi taabii stikeera kiiboordii keessatti mul'atu.", "Xirmooyinka aad ku darto halkan iyo tab-ka stickers-ka kiiboodhka ayay ka muuqdaan.", "تظهر الحزم التي تضيفها هنا وفي تبويب الملصقات في لوحة المفاتيح."),
    "It leaves the keyboard. You can add it again from its link." to r("ከኪቦርዱ ይወጣል። ከአገናኙ እንደገና ሊጨምሩት ይችላሉ።", "ካብ ኪቦርድ ይወጽእ። ካብ ሊንክኡ ዳግማይ ክትውስኾ ትኽእል።", "Kiiboordii keessaa ba'a. Linkii isaa irraa deebi'ee dabaluu dandeessa.", "Waxay ka baxaysaa kiiboodhka. Mar kale ayaad ku dari kartaa xiriirkeeda.", "ستُزال من لوحة المفاتيح. يمكنك إضافتها مجددًا من رابطها."),
    "Remove" to r("አስወግድ", "ኣጥፍእ", "Haqi", "Ka saar", "إزالة"),
    "Keep" to r("አቆይ", "ዕቅብ", "Eegi", "Haay", "إبقاء"),

    // AI
    "Akai server address" to r("የአካይ አገልጋይ አድራሻ", "ኣድራሻ ኣገልጋሊ ኣካይ", "Teessoo sarvara Akai", "Cinwaanka server-ka Akai", "عنوان خادم Akai"),
    "Translation runs on the Akai web server. Leave blank to use the Akai website, or enter your own. Handwriting is read on the phone, and uses the server only if that fails." to r(
        "ትርጉም በአካይ ድር አገልጋይ ላይ ይሠራል። የአካይን ድረ ገጽ ለመጠቀም ባዶ ይተዉ ወይም የራስዎን ያስገቡ። የእጅ ጽሕፈት በስልኩ ላይ ይነበባል፣ ካልተሳካ ብቻ አገልጋዩን ይጠቀማል።",
        "ትርጉም ኣብ ኣገልጋሊ ወብ ኣካይ ይሰርሕ። ወብሳይት ኣካይ ንምጥቃም ባዶ ግደፎ ወይ ናትካ የእትዎ። ናይ ኢድ ጽሑፍ ኣብ ሞባይል ይንበብ፣ እንተዘይተዓዊቱ ጥራይ ኣገልጋሊ ይጥቀም።",
        "Hiikkaan sarvara weebii Akai irratti hojjeta. Weebsaayitii Akai fayyadamuuf duwwaa dhiisi, ykn kan kee galchi. Barreeffamni harkaa bilbila irratti dubbifama; yoo hin milkoofne qofa sarvara fayyadama.",
        "Turjumaaddu waxay ka shaqaysaa server-ka web-ka Akai. Banaan u dhig si aad u isticmaasho website-ka Akai, ama geli kaaga. Far-gacmeedka waxaa lagu akhriyaa taleefanka, server-kana waa la isticmaalaa haddii uu guuldaraysto oo keliya.",
        "تعمل الترجمة على خادم Akai. اتركه فارغًا لاستخدام موقع Akai أو أدخل خادمك. تُقرأ الكتابة اليدوية على الهاتف ولا يُستخدم الخادم إلا إذا فشلت.",
    ),

    // Setup / About
    "✓  Turned on" to r("✓  በርቷል", "✓  በሪሑ", "✓  Jalqabsiifameera", "✓  Waa daaran yahay", "✓  تم التفعيل"),
    "1.  Turn Akai on in system settings" to r("1.  አካይን በስርዓት ቅንብሮች ውስጥ ያብሩ", "1.  ኣካይ ኣብ ቅጥዕታት ስርዓት ኣብርሁ", "1.  Akai qindaa'inoota sirnaa keessatti jalqabsiisi", "1.  Daar Akai dejinta nidaamka", "1.  فعّل Akai من إعدادات النظام"),
    "✓  Chosen as your keyboard" to r("✓  እንደ ኪቦርድዎ ተመርጧል", "✓  ከም ኪቦርድካ ተመሪጹ", "✓  Akka kiiboordii keessanitti filatameera", "✓  Waa la doortay kiiboodhkaaga", "✓  تم اختياره كلوحة مفاتيحك"),
    "2.  Choose Akai as your keyboard" to r("2.  አካይን እንደ ኪቦርድዎ ይምረጡ", "2.  ኣካይ ከም ኪቦርድካ ምረጽ", "2.  Akai akka kiiboordii keessanitti filadhu", "2.  Dooro Akai kiiboodhkaaga", "2.  اختر Akai كلوحة مفاتيحك"),
    "Choose Akai as your keyboard" to r("አካይን እንደ ኪቦርድዎ ይምረጡ", "ኣካይ ከም ኪቦርድካ ምረጽ", "Akai akka kiiboordii keessanitti filadhu", "Dooro Akai kiiboodhkaaga", "اختر Akai كلوحة مفاتيحك"),
    "Each box asks for a different kind of keyboard." to r("እያንዳንዱ ሳጥን የተለየ የኪቦርድ አይነት ይጠይቃል።", "ነፍሲ ወከፍ ሳጹን ፍሉይ ዓይነት ኪቦርድ ይሓትት።", "Daandiin hundi gosa kiiboordii adda ta'e gaafata.", "Sanduuq kasta wuxuu weydiisanayaa nooc kiiboodh oo kala duwan.", "كل مربع يطلب نوعًا مختلفًا من لوحات المفاتيح."),
    "Text" to r("ጽሑፍ", "ጽሑፍ", "Barreeffama", "Qoraal", "نص"),
    "Phone number" to r("የስልክ ቁጥር", "ቍጽሪ ስልኪ", "Lakkoofsa bilbilaa", "Lambarka taleefanka", "رقم الهاتف"),
    "Number" to r("ቁጥር", "ቍጽሪ", "Lakkoofsa", "Lambar", "رقم"),
    "Email" to r("ኢሜይል", "ኢሜይል", "Imeelii", "Email", "البريد الإلكتروني"),
    "Akai Keyboard" to r("አካይ ኪቦርድ", "ኣካይ ኪቦርድ", "Kiiboordii Akai", "Kiiboodhka Akai", "لوحة مفاتيح Akai"),
    "A bilingual English and Amharic keyboard, with fidel and phonetic typing, live themes, emoji, GIFs, handwriting and translation." to r(
        "ባለሁለት ቋንቋ የእንግሊዝኛና የአማርኛ ኪቦርድ፣ በፊደልና በድምጻዊ ትየባ፣ ሕያው ገጽታዎች፣ ሺሸንፎች፣ GIFዎች፣ የእጅ ጽሕፈትና ትርጉም ያለው።",
        "ክልተ ቋንቋ ናይ እንግሊዝኛን ኣምሓርኛን ኪቦርድ፣ ብፊደልን ድምጻዊን ምጽሓፍ፣ ህያዋን ገጽታታት፣ ኢሞጂ፣ GIFs፣ ናይ ኢድ ጽሑፍን ትርጉምን ዘለዎ።",
        "Kiiboordii afaan lamaa Ingliffaa fi Amaariffaa, barreessuu fidel fi sagaleen, teemiiwwan jiraatan, emojii, GIF, barreeffama harkaa fi hiikkaan.",
        "Kiiboodh laba-luqadood Ingiriisi iyo Amxaari, oo leh qorista fidel iyo codka, qaabab nool, emoji, GIF, far-gacmeed iyo turjumaad.",
        "لوحة مفاتيح ثنائية اللغة بالإنجليزية والأمهرية، مع الكتابة بالفيدل والصوتية، وسمات حية ورموز تعبيرية وصور GIF وكتابة يدوية وترجمة.",
    ),
    "Website" to r("ድረ ገጽ", "ወብሳይት", "Weebsaayitii", "Website", "الموقع"),
    "Learned words and settings are kept on this phone, and words are never learned from password, email or number fields. Text goes to your Akai server only when you use Translate, or for handwriting the phone can't read. GIFs come from Giphy through the Akai server (or directly, with your own key), and voice typing uses your phone's speech service." to r(
        "የተማሩ ቃላትና ቅንብሮች በዚህ ስልክ ላይ ይቀመጣሉ፣ ከይለፍ ቃል፣ ኢሜይል ወይም ቁጥር መስኮች ቃላት በፍጹም አይማሩም። ጽሑፍ ወደ አካይ አገልጋይ የሚሄደው ትርጉም ሲጠቀሙ ወይም ስልኩ ማንበብ ለማይችለው የእጅ ጽሕፈት ብቻ ነው። GIFዎች ከGiphy በአካይ አገልጋይ (ወይም በራስዎ ቁልፍ በቀጥታ) ይመጣሉ፣ የድምጽ ትየባ የስልክዎን የንግግር አገልግሎት ይጠቀማል።",
        "ዝተማህርናዮም ቃላትን ቅጥዕታትን ኣብዚ ሞባይል ይቕመጡ፣ ካብ ቃል ምስጢር፣ ኢሜይል ወይ ቍጽሪ መዳያታት ቃላት ፈጺሙ ኣይማሃሩን። ጽሑፍ ናብ ኣገልጋሊ ኣካይ ዝኸይድ ትርጉም ክትጥቀም ከለኻ ወይ ሞባይል ዘይከኣለ ናይ ኢድ ጽሑፍ ጥራይ እዩ። GIFs ካብ Giphy ብኣገልጋሊ ኣካይ (ወይ ብናትካ መፍትሕ ብቕጥታ) ይመጹ፣ ምጽሓፍ ብድምጺ ኣገልግሎት ዘረባ ሞባይልካ ይጥቀም።",
        "Jechoonni barataman fi qindaa'inoonni bilbila kana irra ni kuufamu, jechoonni dirree jecha darbaa, imeelii ykn lakkoofsaa irraa gonkumaa hin barataman. Barreeffamni sarvara Akai'tti kan deemu yeroo Hiikkaa fayyadamtan, ykn barreeffama harkaa bilbilli dubbisuu hin dandeenye qofa. GIF'n Giphy irraa sarvara Akai'tiin (ykn furtuu mataa keessanitiin kallattiin) dhufa; barreessuun sagalee tajaajila haasaa bilbila keessanii fayyadama.",
        "Erayada la bartay iyo dejinta waxaa lagu hayaa taleefankan, erayadana marnaba lagama barto goobaha furaha sirta, email ama lambarka. Qoraalku wuxuu aadaa server-ka Akai oo keliya marka aad isticmaasho Turjun, ama far-gacmeed taleefanku akhriyi waayo. GIF-yada waxay ka yimaadaan Giphy iyagoo mara server-ka Akai (ama si toos ah, furahaaga), qorista codkuna waxay isticmaashaa adeegga hadalka taleefankaaga.",
        "تُحفظ الكلمات المتعلَّمة والإعدادات على هذا الهاتف، ولا تُتعلَّم الكلمات أبدًا من حقول كلمة المرور أو البريد أو الأرقام. يذهب النص إلى خادم Akai فقط عند استخدام الترجمة أو للكتابة اليدوية التي لا يستطيع الهاتف قراءتها. تأتي صور GIF من Giphy عبر خادم Akai (أو مباشرة بمفتاحك)، وتستخدم الكتابة الصوتية خدمة الكلام في هاتفك.",
    ),

